function g(id)         { const e=document.getElementById(id); return e?e.value.trim():''; }
function setVal(id,v)  { const e=document.getElementById(id); if(e) e.value=v||''; }
function rand(arr)     { return arr[Math.floor(Math.random()*arr.length)]; }
function randInt(a,b)  { return Math.floor(Math.random()*(b-a+1))+a; }
function escHtml(s)    { if(!s)return''; const d=document.createElement('div'); d.textContent=s; return d.innerHTML; }
function todayStr()    { return new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'long',year:'numeric'}); }
function todayISO()    { return new Date().toISOString().slice(0,10); }
function fmtDate(s)    { if(!s)return'—'; const d=new Date(s+'T00:00:00'); return d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}); }
function genCaseRef()  { return 'CMU-'+Date.now().toString(36).toUpperCase().slice(-6); }

function shadeToColor(shade) {
  const m={'A1':'#f5ead0','A2':'#f0e0b8','A3':'#e8d09e','A3.5':'#e0c48a','A4':'#d4b070',
           'B1':'#f5e8c8','B2':'#eedfc0','B3':'#e5d0a4','B4':'#d8c090',
           'C1':'#eedfb8','C2':'#e6d5a8','C3':'#dcc890','D2':'#e8d8a8','D3':'#dfd0a0'};
  return m[shade]||'#e8dcc8';
}

function getWorkflow() {
  return Array.from(document.querySelectorAll('#workflowGroup input:checked')).map(cb=>cb.value);
}

// ══════════════════════════════════════════════
// ARCH SVG GENERATOR
// Draws teeth along a real horseshoe arch curve
// matching the style of the uploaded Teeth_arch.jpg
// ══════════════════════════════════════════════

// Arch tooth positions computed along an elliptical arc
// Upper arch: arc opens downward; Lower arch: opens upward
// cx/cy = centre of ellipse, rx/ry = semi-axes, start/end angle in radians
// Returns array of {x, y, angle} for each tooth position

function archPositions(cx, cy, rx, ry, startDeg, endDeg, count) {
  const pts = [];
  for(let i=0; i<count; i++) {
    const t = (startDeg + (endDeg - startDeg) * i / (count-1)) * Math.PI / 180;
    pts.push({
      x: cx + rx * Math.cos(t),
      y: cy + ry * Math.sin(t),
      t
    });
  }
  return pts;
}

// Tooth shape sizes based on FDI number (molar larger than incisor)
function toothSize(fdi) {
  const n = fdi % 10; // tooth number in quadrant
  if(n >= 7) return {w:12,h:14}; // 3rd molar
  if(n === 6) return {w:11,h:13}; // 1st/2nd molar
  if(n === 5) return {w:9,h:12};  // 2nd premolar
  if(n === 4) return {w:9,h:12};  // 1st premolar
  if(n === 3) return {w:8,h:13};  // canine
  if(n === 2) return {w:7,h:11};  // lateral incisor
  if(n === 1) return {w:8,h:11};  // central incisor
  return {w:8,h:11};
}

function toothStateClass(fdi, toothStates) {
  const s = toothStates[fdi];
  if(s==='abutment') return 'tooth-abutment';
  if(s==='pontic')   return 'tooth-pontic';
  if(s==='missing')  return 'tooth-missing';
  return 'tooth-normal';
}

function buildArchSVG(toothStates) {
  // SVG canvas
  const W=240, H=320;
  // Upper arch: ellipse centred at (120, 155), rx=105, ry=80
  // Teeth go from 180° (far left) to 0° (far right) along the TOP of ellipse
  // i.e. from -175° to -5° (upper part of ellipse, y decreasing toward top)
  const UCX=120, UCY=160, URX=105, URY=82;
  const LCX=120, LCY=175, LRX=90,  LRY=70;

  // Upper arch: teeth arranged from patient's upper-right (18) to upper-left (28)
  // Along the arc from about 195° to -15° going clockwise
  const uPts = archPositions(UCX, UCY, URX, URY, 197, 343, 16);
  // Lower arch: teeth arranged from patient's lower-right (48) to lower-left (38)
  // Lower ellipse, arc from about 163° to 17° going counter-clockwise (bottom of ellipse)
  const lPts = archPositions(LCX, LCY, LRX, LRY, 197, 343, 16);

  let teeth = '';

  // Upper teeth
  UPPER_TEETH.forEach((fdi, i) => {
    const p = uPts[i];
    const sz = toothSize(fdi);
    const cls = toothStateClass(fdi, toothStates);
    // Rotate tooth to be tangent to arch (perpendicular to radius)
    const angleDeg = (p.t * 180/Math.PI) + 90;
    // Number position: above upper teeth (toward outside of arch = away from centre)
    const numR = 1.22;
    const nx = UCX + URX*numR * Math.cos(p.t);
    const ny = UCY + URY*numR * Math.sin(p.t);
    teeth += `<g transform="translate(${p.x},${p.y}) rotate(${angleDeg})">
      <rect x="${-sz.w/2}" y="${-sz.h/2}" width="${sz.w}" height="${sz.h}" rx="2.5" ry="2" class="${cls}"/>
    </g>
    <text x="${nx}" y="${ny}" text-anchor="middle" dominant-baseline="middle"
      font-size="5" font-family="DM Mono,monospace" fill="#6b6760">${fdi}</text>`;
  });

  // Lower teeth
  LOWER_TEETH.forEach((fdi, i) => {
    const p = lPts[i];
    const sz = toothSize(fdi);
    const cls = toothStateClass(fdi, toothStates);
    const angleDeg = (p.t * 180/Math.PI) + 90;
    const numR = 1.28;
    const nx = LCX + LRX*numR * Math.cos(p.t);
    const ny = LCY + LRY*numR * Math.sin(p.t);
    teeth += `<g transform="translate(${p.x},${p.y}) rotate(${angleDeg})">
      <rect x="${-sz.w/2}" y="${-sz.h/2}" width="${sz.w}" height="${sz.h}" rx="2.5" ry="2" class="${cls}"/>
    </g>
    <text x="${nx}" y="${ny}" text-anchor="middle" dominant-baseline="middle"
      font-size="5" font-family="DM Mono,monospace" fill="#6b6760">${fdi}</text>`;
  });

  // Midline label
  const midline = `
    <line x1="120" y1="80" x2="120" y2="255" stroke="#d4d0c8" stroke-width="0.5" stroke-dasharray="3 2"/>
    <text x="122" y="167" font-size="5.5" fill="#b0ab9e" font-family="DM Mono,monospace">mid</text>
    <text x="28" y="103" font-size="6" fill="#8b1a2f" font-weight="bold" font-family="DM Mono,monospace">UR</text>
    <text x="192" y="103" font-size="6" fill="#8b1a2f" font-weight="bold" font-family="DM Mono,monospace">UL</text>
    <text x="28" y="236" font-size="6" fill="#8b1a2f" font-weight="bold" font-family="DM Mono,monospace">LR</text>
    <text x="192" y="236" font-size="6" fill="#8b1a2f" font-weight="bold" font-family="DM Mono,monospace">LL</text>
  `;

  return `<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg">
    <style>
      .tooth-normal   { fill:#f0ece5; stroke:#a8a49c; stroke-width:0.8; }
      .tooth-abutment { fill:#1a3a5c; stroke:#0d2740; stroke-width:0.8; }
      .tooth-pontic   { fill:#fdf6e0; stroke:#a07d10; stroke-width:0.8; }
      .tooth-missing  { fill:#f7eaec; stroke:#8b1a2f; stroke-width:0.8; stroke-dasharray:2 1.5; }
    </style>
    ${midline}
    ${teeth}
  </svg>`;
}

// ── Control-side small arch ──
function buildControlArch(containerId, teeth, upper, toothStates, cx, cy, rx, ry, startDeg, endDeg) {
  const container = document.getElementById(containerId);
  if(!container) return;
  container.innerHTML='';
  const pts = archPositions(cx, cy, rx, ry, startDeg, endDeg, teeth.length);
  teeth.forEach((fdi, i)=>{
    const el=document.createElement('div');
    el.className='tcc-tooth';
    el.dataset.fdi=fdi;
    if(toothStates[fdi]) el.classList.add('state-'+toothStates[fdi]);
    el.innerHTML=`<svg viewBox="0 0 18 22" xmlns="http://www.w3.org/2000/svg">
      <path d="${upper
        ? 'M3 20 C2 16 1 12 1 8 C1 3 4 1 9 1 C14 1 17 3 17 8 C17 12 16 16 15 20 Z'
        : 'M3 2 C2 6 1 10 1 14 C1 19 4 21 9 21 C14 21 17 19 17 14 C17 10 16 6 15 2 Z'}"/>
    </svg><span class="tnum">${fdi}</span>`;
    el.addEventListener('click', ()=>cycleToothState(fdi, el));
    container.appendChild(el);
  });
}

function buildControlChart() {
  toothChartControl.innerHTML=`
    <div style="font-size:9px;color:var(--muted);margin-bottom:3px;font-weight:600;">UPPER&nbsp;&nbsp;&#8679;</div>
    <div class="tcc-arch" id="ctrl-upper" style="flex-wrap:wrap;gap:1px;justify-content:center;"></div>
    <div style="height:5px"></div>
    <div class="tcc-arch" id="ctrl-lower" style="flex-wrap:wrap;gap:1px;justify-content:center;"></div>
    <div style="font-size:9px;color:var(--muted);margin-top:3px;font-weight:600;">LOWER&nbsp;&nbsp;&#8681;</div>
  `;
  // flat linear layout for the control panel (arch SVG is on the output only)
  buildControlArch('ctrl-upper', UPPER_TEETH, true,  state.toothStates, 0,0,0,0,0,0);
  buildControlArch('ctrl-lower', LOWER_TEETH, false, state.toothStates, 0,0,0,0,0,0);
}

// Re-render control chart as simple rows
function rebuildControlChart() {
  const upper = document.getElementById('ctrl-upper');
  const lower = document.getElementById('ctrl-lower');
  if(!upper||!lower) return;
  [upper, lower].forEach((container, isLower)=>{
    const teeth = isLower ? LOWER_TEETH : UPPER_TEETH;
    const isUpperBool = !isLower;
    container.innerHTML='';
    teeth.forEach(fdi=>{
      const el=document.createElement('div');
      el.className='tcc-tooth';
      el.dataset.fdi=fdi;
      if(state.toothStates[fdi]) el.classList.add('state-'+state.toothStates[fdi]);
      el.innerHTML=`<svg viewBox="0 0 18 22" xmlns="http://www.w3.org/2000/svg">
        <path d="${isUpperBool
          ? 'M3 20 C2 16 1 12 1 8 C1 3 4 1 9 1 C14 1 17 3 17 8 C17 12 16 6 15 2 Z'
          : 'M3 2 C2 6 1 10 1 14 C1 19 4 21 9 21 C14 21 17 19 17 14 C17 10 16 6 15 2 Z'}"/>
      </svg><span class="tnum">${fdi}</span>`;
      el.addEventListener('click', ()=>cycleToothState(fdi, el));
      container.appendChild(el);
    });
  });
}

function cycleToothState(fdi, el) {
  const mode = toothModeSelect.value;
  if(state.toothStates[fdi]===mode){
    delete state.toothStates[fdi];
    el.classList.remove('state-abutment','state-pontic','state-missing');
  } else {
    state.toothStates[fdi]=mode;
    el.classList.remove('state-abutment','state-pontic','state-missing');
    el.classList.add('state-'+mode);
  }
}

