function randomDOB(){
  const y=randInt(1945,2008), m=String(randInt(1,12)).padStart(2,'0'), d=String(randInt(1,28)).padStart(2,'0');
  return `${y}-${m}-${d}`;
}
function randomFuture(minD=7,maxD=28){
  const d=new Date(); d.setDate(d.getDate()+randInt(minD,maxD)); return d.toISOString().slice(0,10);
}

